(() => {
  const isUsable = (color) => {
    if (!color || color === 'transparent') return false;
    const match = color.match(/rgba?\\(([^)]+)\\)/);
    if (!match) return true;
    const parts = match[1].split(',').map((part) => part.trim());
    return parts.length < 4 || Number(parts[3]) > 0.05;
  };
  const inheritedBackground = (node) => {
    let current = node;
    while (current && current.nodeType === Node.ELEMENT_NODE) {
      const color = getComputedStyle(current).backgroundColor;
      if (isUsable(color)) return color;
      current = current.parentElement;
    }
    return '';
  };
  const samples = [
    document.elementFromPoint(Math.floor(window.innerWidth / 2), 1),
    document.elementFromPoint(1, 1),
    document.elementFromPoint(Math.max(window.innerWidth - 1, 1), 1),
    document.querySelector('header,[role="banner"],nav,.navbar,.header,.topbar'),
    document.body,
    document.documentElement,
  ];
  for (const node of samples) {
    const color = inheritedBackground(node);
    if (isUsable(color)) return color;
  }
  return document.querySelector('meta[name="theme-color"]')?.content || '';
})()
